    /**
     * Method to retrieve the Model via ModelFetchOneSummary
     * @param 	summary ModelFetchOneSummary 
     * @return 	ModelFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Model getModel( ModelFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ModelFetchOneSummary arg cannot be null" );
    	
    	Model entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Model
        	// --------------------------------------
        	CompletableFuture<Model> futureEntity = queryGateway.query(new FindModelQuery( new LoadModelFilter( summary.getModelId() ) ), ResponseTypes.instanceOf(Model.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Model with id " + summary.getModelId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


